}
console.log(forms);

// 2. Read app.js to find routes or API endpoints called
console.log('\n--- API CALLS IN APP.JS ---');
const appContent = fs.readFileSync(path.join(projectDir, 'app.js'), 'utf8');
const fetchRegex = /fetch\s*\(\s*["'`](\/api\/[a-zA-Z0-9_-]+|https?:\/\/[^\s"'`]+)["'`]/g;
