220: function initDB() {
221:     return new Promise((resolve, reject) => {
222:         const request = indexedDB.open(DB_NAME, 1);
223:         request.onupgradeneeded = (e) => {
224:             const db = e.target.result;
225:             if (!db.objectStoreNames.contains(STORE_NAME)) {
226:                 db.createObjectStore(STORE_NAME);
227:             }
228:         };
229:         request.onsuccess = () => resolve(request.result);
230:         request.onerror = () => reject(request.error);
231:     });
232: }
