234: async function savePdfToDB(base64Data) {
235:     const db = await initDB();
236:     return new Promise((resolve, reject) => {
237:         const tx = db.transaction(STORE_NAME, 'readwrite');
238:         const store = tx.objectStore(STORE_NAME);
239:         store.put(base64Data, 'knowledge_pdf');
240:         tx.oncomplete = () => resolve();
241:         tx.onerror = () => reject(tx.error);
242:     });
243: }
