245: async function loadPdfFromDB() {
246:     const db = await initDB();
247:     return new Promise((resolve, reject) => {
248:         const tx = db.transaction(STORE_NAME, 'readonly');
249:         const store = tx.objectStore(STORE_NAME);
250:         const request = store.get('knowledge_pdf');
251:         request.onsuccess = () => resolve(request.result);
252:         request.onerror = () => reject(request.error);
253:     });
254: }
