278:             if (statusText) {
279:                 statusText.style.color = 'var(--danger-red)';
280:                 statusText.innerText = "❌ Gagal menyimpan PDF: " + err.message;
281:             }
282:         }
283:     };
284:     reader.readAsDataURL(file);
285: }
