const fs = require('fs');
const path = require('path');

async function runTest() {
    const payload = {
        namaNasabah: "Budi Santoso",
        namaAgen: "Rian Aditya",
        jenisAsuransi: "Asuransi Kendaraan All Risk",
        nilaiPertanggungan: 250000000,
        totalPremi: 5725000,
        catatanTambahan: "Diskon 10% khusus nasabah baru."
    };

    console.log("Mengirim request ke http://localhost:3001/api/generate-pptx...");
    try {
        const res = await fetch('http://localhost:3001/api/generate-pptx', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        if (!res.ok) {
            const text = await res.text();
            throw new Error(`HTTP Error: ${res.status} - ${text}`);
        }

        const buffer = await res.arrayBuffer();
        const outputPath = path.join(__dirname, 'test_output.pptx');
        fs.writeFileSync(outputPath, Buffer.from(buffer));
        console.log(`[✅] Berhasil mengunduh PPTX dan menyimpan ke: ${outputPath}`);
        console.log(`Ukuran file: ${(buffer.byteLength / 1024).toFixed(2)} KB`);
    } catch(err) {
        console.error("[❌] Error dalam testing:", err.message);
    }
}

runTest();
